mapper.select:
SELECT `ts`, `id`, `report_time`, `tenant_id`, `server_id`, `upstream`, `reply`, `identifier`, `request_id`, `method`, `params`, `data`, `code`, `msg` FROM `boer`.`device_message_${reqVO.deviceId}`
AND `method` = '${reqVO.method}'
AND `upstream` = ${reqVO.upstream}
AND `reply` = ${reqVO.reply}
AND `identifier` = '${reqVO.identifier}'
ORDER BY `ts` DESC

SELECT TIMETRUNCATE(`ts`, 1h) AS `time`, SUM(CASE WHEN `upstream` = true THEN 1 ELSE 0 END) AS `upstream_count`, SUM(CASE WHEN `upstream` = false THEN 1 ELSE 0 END) AS `downstream_count` FROM `boer`.`device_message`
AND `ts` >= ${startTime}
AND `ts` <= ${endTime}
GROUP BY TIMETRUNCATE(`ts`, 1h)
